#include <iostream>
#include <array>
#include <string_view>

constexpr int NUMBER_OF_LETTERS = 26;

void countLetters(std::string_view text, std::array<int, NUMBER_OF_LETTERS>& counts) {
    counts.fill(0);
    for (char ch : text) {
        if (ch >= 'a' && ch <= 'z') {
            counts[ch - 'a']++;
        }
    }
}

void displayCounts(const std::array<int, NUMBER_OF_LETTERS>& counts) {
    int printed = 0;
    for (int i = 0; i < NUMBER_OF_LETTERS; ++i) {
        if (counts[i] > 0) {
            std::cout << counts[i] << " " << static_cast<char>('a' + i) << " ";
            printed++;
            if (printed % 5 == 0) {
                std::cout << "\n";
            }
        }
    }
    if (printed % 5 != 0) {
        std::cout << "\n";
    }
}

int main() {
    // Deterministic fixed input: "abracadabraz"
    // Counts: 'a': 5, 'b': 2, 'c': 1, 'd': 1, 'r': 2, 'z': 1
    constexpr std::string_view sampleText = "abracadabraz";
    std::array<int, NUMBER_OF_LETTERS> counts{};

    countLetters(sampleText, counts);
    std::cout << "Occurrences:\n";
    displayCounts(counts);

    return 0;
}

#include <iostream>

// Linear search: works on any array order
int linearSearch(const int list[], int key, int arraySize) {
    for (int i = 0; i < arraySize; ++i) {
        if (key == list[i]) {
            return i;
        }
    }
    return -1;
}

// Binary search: requires presorted array
// Version 2 implementation from textbook with overflow-safe mid calculation
int binarySearch(const int list[], int key, int listSize) {
    int low = 0;
    int high = listSize - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (key < list[mid]) {
            high = mid - 1;
        } else if (key == list[mid]) {
            return mid;
        } else {
            low = mid + 1;
        }
    }
    return -1;
}

int main() {
    int rawList[] = {1, 4, 4, 2, 5, -3, 6, 2};
    int sortedList[] = {2, 4, 7, 10, 11, 45, 50, 59, 60, 66, 69, 70, 79};

    // Test linearSearch on unsorted list
    std::cout << "LinearSearch 4: " << linearSearch(rawList, 4, 8) << "\n";
    std::cout << "LinearSearch -4: " << linearSearch(rawList, -4, 8) << "\n";

    // Test binarySearch on sorted list
    std::cout << "BinarySearch 11: " << binarySearch(sortedList, 11, 13) << "\n";
    std::cout << "BinarySearch 12: " << binarySearch(sortedList, 12, 13) << "\n";

    return 0;
}
